import type { ReactNode } from "react";

/** Text with a band of light sweeping across it, for a loading message or a quiet accent. The words stay real text: selectable and read as normal. */
export interface TextShimmerSpecProps {
  /**
   * The text.
   */
  children: ReactNode;
  /**
   * Seconds for one sweep.
   * @default 2.8
   */
  duration?: number;
  /**
   * The resting colour of the text, any CSS colour. Defaults to the muted text colour.
   */
  baseColor?: string;
  /**
   * The colour of the passing light, any CSS colour. Defaults to the main text colour.
   */
  highlightColor?: string;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
}

export const textShimmerDefaults = {
  duration: 2.8,
  isPaused: false,
} as const;

export const textShimmerMeta = {
  "name": "TextShimmer",
  "version": "0.1.0",
  "status": "experimental",
  "role": "text"
} as const;
